    } as React.CSSProperties}>
      {/* Render full form. Each field is a labeled input/select.
          Style: label 12px stoneDark, input padding 11px 14px, border 1px BRAND.border, borderRadius 10, focus rust outline.
          Show field-level errors below each input in BRAND.crimson 11px.
          Two-column grid for: chairs + preferredTime.
