        <FormSelect label="Chairs" name="chairs" error={state.errors?.chairs} required options={[
          { value: '', label: 'Select…', disabled: true },
          { value: '1', label: '1 (solo)' },
          { value: '2-5', label: '2 – 5' },
          { value: '6-10', label: '6 – 10' },
          { value: '11+', label: '11+' },
        ]} />
        <FormSelect label="Preferred time" name="preferredTime" error={state.errors?.preferredTime} required options={[
          { value: '', label: 'Select…', disabled: true },
          { value: 'weekday-am', label: 'Weekday morning' },
          { value: 'weekday-pm', label: 'Weekday afternoon' },
          { value: 'weekend', label: 'Weekend' },
          { value: 'flexible', label: "I'm flexible" },
