          borderRadius: 8,
          fontFamily: FONT.sans,
          fontSize: 13,
          marginBottom: 16,
        } as React.CSSProperties}>{state.message}</div>
      )}

      {/* Submit */}
      <button
        type="submit"
        disabled={pending}
        style={{
          width: '100%',
          padding: '14px 20px',
          borderRadius: 100,
          background: BRAND.onyx,
          color: BRAND.bone,
          fontFamily: FONT.sans,
          fontSize: 15,
          fontWeight: 600,
          border: 'none',
          cursor: pending ? 'wait' : 'pointer',
          opacity: pending ? 0.7 : 1,
          display: 'inline-flex',
